import{_ as e,o as a,c as n,ah as o}from"./chunks/framework.e_ysbW9u.js";const r="/projects/ROSPug/en/latest/assets/image3.C9AFC1wi.png",i="/projects/ROSPug/en/latest/assets/1.DmYY8Ovz.png",s="/projects/ROSPug/en/latest/assets/2.o1mJHgb-.png",l="/projects/ROSPug/en/latest/assets/3.DkugwduZ.png",c="/projects/ROSPug/en/latest/assets/4.Cuy1wpR-.png",g="/projects/ROSPug/en/latest/assets/5.BpSX3Vtl.png",d="/projects/ROSPug/en/latest/assets/6.CrvzfPlG.png",p="/projects/ROSPug/en/latest/assets/7.DQEPTvIB.png",h="/projects/ROSPug/en/latest/assets/8.CzKL521g.png",u="/projects/ROSPug/en/latest/assets/9.B4nLr-Pf.jpg",m="/projects/ROSPug/en/latest/assets/image2.Colartqm.png",y="/projects/ROSPug/en/latest/assets/image3.-iKF8gBS.png",b="/projects/ROSPug/en/latest/assets/image4.DMdlS0kH.png",_="/projects/ROSPug/en/latest/assets/image5.CzSt7FhF.png",w="/projects/ROSPug/en/latest/assets/image6.CsHbnpqs.png",f="/projects/ROSPug/en/latest/assets/image7.BqE0HiFT.png",x="/projects/ROSPug/en/latest/assets/image2.BxUFbR99.png",v="/projects/ROSPug/en/latest/assets/image4.nF_AKQuF.png",q=JSON.parse('{"title":"1. Getting Ready","description":"","frontmatter":{},"headers":[],"relativePath":"docs/1.Getting_ready.md","filePath":"docs/1.Getting_ready.md"}'),P={name:"docs/1.Getting_ready.md"};function S(O,t,R,k,z,j){return a(),n("div",null,[...t[0]||(t[0]=[o('<h1 id="_1-getting-ready" tabindex="-1">1. Getting Ready <a class="header-anchor" href="#_1-getting-ready" aria-label="Permalink to &quot;1. Getting Ready&quot;">​</a></h1><h2 id="_1-1-introduction-to-rospug" tabindex="-1">1.1 Introduction to ROSPug <a class="header-anchor" href="#_1-1-introduction-to-rospug" aria-label="Permalink to &quot;1.1 Introduction to ROSPug&quot;">​</a></h2><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p><strong>The black ROSPug and the gun-gray ROSPug are only different in appearance; their internal functions and features are exactly the same.</strong></p></div><p>ROSPug is a quadruped robot dog specifically designed for ROS education, integrating the Ubuntu 18.04 system and ROS Melodic robot system.</p><p>It is equipped with advanced hardware components, including the NVIDIA Jetson Nano, high-voltage bus servos, Lidar, and an HD camera. With this high-performance hardware configuration, ROSPug excels in various applications such as robot motion control, mapping, navigation, tracking and obstacle avoidance, autonomous patrolling, human body recognition, and somatosensory interaction.</p><p>Moreover, ROSPug utilizes inverse kinematics, allowing for highly adjustable posture, height, and speed. This feature enhances the user&#39;s control experience, providing excellent maneuverability and customization options.</p><p><strong>1.1.1 Hardware Connection Diagram</strong></p><p>The diagram below shows the connections between the ROSPug robot dog&#39;s mainboard, expansion board, and various hardware modules.</p><img loading="lazy" height="880" width="1267" src="'+r+'" class="common_img"><h2 id="_1-2-packing-list" tabindex="-1">1.2 Packing List <a class="header-anchor" href="#_1-2-packing-list" aria-label="Permalink to &quot;1.2 Packing List&quot;">​</a></h2><p>When receive robot package, check packing list to tally items received. If parts are missing, contact us at <a href="mailto:support@hiwonder.com" target="_blank" rel="noreferrer">support@hiwonder.com</a>.</p><table tabindex="0"><thead><tr><th style="text-align:center;">No.</th><th style="text-align:center;"><strong>Product Name</strong></th><th style="text-align:center;">Quantity</th><th style="text-align:center;"><strong>Picture</strong></th></tr></thead><tbody><tr><td style="text-align:center;">1</td><td style="text-align:center;">ROSPug</td><td style="text-align:center;">1</td><td style="text-align:center;"><img loading="lazy" height="852" src="'+i+'" width="400px"></td></tr><tr><td style="text-align:center;">2</td><td style="text-align:center;">WIFI antennas</td><td style="text-align:center;">2</td><td style="text-align:center;"><img loading="lazy" height="71" width="52" src="'+s+'"></td></tr><tr><td style="text-align:center;">3</td><td style="text-align:center;">12.6V 2A charger(DC 4.0*1.7m)</td><td style="text-align:center;">1</td><td style="text-align:center;"><img loading="lazy" height="492" src="'+l+'" width="300px"></td></tr><tr><td style="text-align:center;">4</td><td style="text-align:center;">Card reader</td><td style="text-align:center;">1</td><td style="text-align:center;"><img loading="lazy" height="500" src="'+c+'" width="60px"></td></tr><tr><td style="text-align:center;">5</td><td style="text-align:center;">Wireless handle</td><td style="text-align:center;">1</td><td style="text-align:center;"><img loading="lazy" height="497" src="'+g+'" width="300px"></td></tr><tr><td style="text-align:center;">6</td><td style="text-align:center;">6.3cm Purple ball</td><td style="text-align:center;">1</td><td style="text-align:center;"><img loading="lazy" height="100" width="100" src="'+d+'"></td></tr><tr><td style="text-align:center;">7</td><td style="text-align:center;">Screwdiwer</td><td style="text-align:center;">1</td><td style="text-align:center;"><img loading="lazy" height="221" src="'+p+'" width="220px"></td></tr><tr><td style="text-align:center;">8</td><td style="text-align:center;">Accessory bag</td><td style="text-align:center;"></td><td style="text-align:center;"><img loading="lazy" height="244" src="'+h+'" width="400px"></td></tr><tr><td style="text-align:center;">9</td><td style="text-align:center;">User manual</td><td style="text-align:center;">1</td><td style="text-align:center;"><img loading="lazy" height="1357" src="'+u+'" width="400px"></td></tr></tbody></table><p id="anchor_1_3"></p><h2 id="_1-3-startup-preparation" tabindex="-1">1.3 Startup Preparation <a class="header-anchor" href="#_1-3-startup-preparation" aria-label="Permalink to &quot;1.3 Startup Preparation&quot;">​</a></h2><p><strong>1.3.1 Charging</strong></p><p>The ROSPug robot dog is powered by an 11.1V high-voltage lithium battery, and it is essential to use the specialized charger included in the kit. Upon receipt, please charge the battery, considering that it must be powered off during transportation and cannot be fully charged.</p><p>Full charge typically takes about 1 hour. For optimal movement performance, it is recommended to charge the battery when the voltage is ≤9.6V.</p><p>(1) Turn OFF the switch on the expansion board.</p><img loading="lazy" height="320" width="553" src="'+m+'" class="common_img" style="width:760px;"><p>(2) Take out the battery wires from the bottom hole.</p><img loading="lazy" height="589" width="864" src="'+y+'" class="common_img" style="width:760px;"><p>(3) Connect the battery by matching the wires: red to red and black to black.</p><img loading="lazy" height="499" width="771" src="'+b+'" class="common_img"><p>(4) Secure the battery cover.</p><img loading="lazy" height="1009" width="1269" src="'+_+'" class="common_img"><p>(5) Connect the provided charger to the DC power port on the Jetson expansion board to charge the robot.</p><img loading="lazy" height="781" width="1269" src="'+w+'" class="common_img"><p><strong>1.3.2 Safety Guideline to LiPo Battery</strong></p><p>(1) Please connect the battery by matching the wires: red to red and black to black before charging and using the robot.</p><p>(2) Use the dedicated charger provided in the kit to charge the robotic dog.</p><p>(3) Connect the charger to the battery without plugging it into the power supply; the indicator light will display green.</p><p>(4) To maintain optimal performance, please charge the battery when the voltage is ≤9.6V.</p><img loading="lazy" height="921" width="953" src="'+f+'" class="common_img"><p>(5) When connecting the battery with the power on, the indicator light will turn red to indicate charging is in progress. Once it turns green, charging is complete. After charging, promptly disconnect the cable and switch to avoid overcharging.</p><p>(6) If the robot will not be used for an extended period, fully charge the battery and then disconnect it from the robot. Avoid pulling directly on the wires when disconnecting to prevent damage to the connectors.</p><p>(7) Store the battery in a cool, dry place, away from heat and liquids to prevent overheating, fire, or moisture damage, which can degrade its performance and lifespan.</p><p>(8) Do not hit, throw, or step on the battery.</p><p>(9) Avoid using the battery in areas with strong static or magnetic fields, as this can damage its safety protection features and create hazards.</p><p>(10) Do not connect the battery&#39;s positive and negative terminals with metal objects to prevent short circuits.</p><p>(11) Do not plug the battery into a power outlet.</p><p>(12) Do not throw the battery into fire or a heater.</p><p>(13) Do not store or transport the battery with metal objects, such as hairpins or necklaces.</p><h2 id="_1-4-initial-startup" tabindex="-1">1.4 Initial Startup <a class="header-anchor" href="#_1-4-initial-startup" aria-label="Permalink to &quot;1.4 Initial Startup&quot;">​</a></h2><p><strong>1.4.1 Notes</strong></p><p>(1) To ensure stable performance, recharge the battery if its level falls below 10V before proceeding with operation. For detailed charging instructions, refer to <a href="#anchor_1_3">1.3 Startup Preparation</a> .</p><p>(2) Keep the robot at a distance from your face and eyes during movement to prevent accidental injury.</p><p>(3) During robot operation, avoid placing fingers within the robot&#39;s joint movement range to prevent injury.</p><p>(4) Exercise caution to prevent the robot from falling off edges during movement.</p><p>(5) If the robot operates continuously for an extended period, the servos may heat up. Allow the robot to &quot;<strong>rest</strong>&quot; until the servos cool down before resuming operation.</p><p>(6) The robot&#39;s servos are precision components and consumables. Consider replacing them after prolonged or excessive use.</p><p><strong>1.4.2 Startup Notice</strong></p><p>(1) Before powering on, ensure all connections on the main controller are securely plugged in. Pay particular attention to the servo wires, OLED module, HD camera, controller, and radar connections.</p><p>(2) To prevent damage to the robot caused by sudden force upon startup, place the robot as shown in the picture.</p><img loading="lazy" height="362" width="779" src="'+x+'" class="common_img"><p>(3) Switch ON the expansion board. LED1 will emit a faint blue light, and after 20 to 30 seconds, it will begin flashing. Soon after, LED1 will stay solid, and the OLED module at the rear will display the current voltage. At this point, the robot dog will shift to its initial posture, signaling that the ROS configuration is complete and the device is fully powered up.</p><img loading="lazy" height="820" width="1268" src="'+v+'" class="common_img"><p>(4) The default network connection mode is AP Direct Connection mode. Once the robot boots up successfully, it will generate a WiFi starting with the letter of <strong>&quot;HW&quot;,</strong> and the initial password is <strong>&quot;hiwonder&quot;</strong>.</p>',57)])])}const C=e(P,[["render",S]]);export{q as __pageData,C as default};
